function source(title, urlOrReference, relevantClaim) {
  return Object.freeze({
    title,
    organisationOrAuthor: title.includes("World Heritage") ? "UNESCO World Heritage Centre" : "UNESCO Intangible Cultural Heritage",
    urlOrReference,
    publicationDate: null,
    accessDate: ACCESS_DATE,
    sourceType: "heritage",
    reviewStatus: "approved",
    relevantClaim,
  });
}

