const sensitive = Object.freeze({
  living: "Living cultural practice: require review by practitioners from the named community and do not generalize beyond the documented scope.",
  sacred: "Sacred or religious material: use only public-source details and require review by the relevant practitioners and knowledge-holders.",
  gender: "Gendered practice or space: community review must confirm respectful wording and avoid presenting a documented role as fixed or universal.",
  colonial: "Colonialism, enslavement or violence: trauma-informed historical and community review is required before progression beyond draft.",
  oral: "Oral tradition: community review is required and the narrative must not be reframed as independently verified chronology.",
  identity: "Identity terminology and community scope require review by people from the named communities, including preferred names and spellings.",
  archaeology: "Ancient religious, funerary or political history requires specialist archaeological and local heritage review; modern identities must not be inferred from it.",
  environment: "Living environmental knowledge and resource use require local practitioner and conservation review before progression.",
  disputed: "Regional classification, borders or political framing are sensitive; require local and specialist review and do not imply a position on sovereignty.",
});

